PRAGMA foreign_keys = ON;

ALTER TABLE uploads ADD COLUMN school_id TEXT;
ALTER TABLE schools ADD COLUMN last_seen_period TEXT;
ALTER TABLE schools ADD COLUMN is_master INTEGER NOT NULL DEFAULT 1;

DROP INDEX IF EXISTS uploads_dedupe_idx;
CREATE UNIQUE INDEX IF NOT EXISTS uploads_dedupe_idx
  ON uploads(module, checksum_sha256, reporting_period, COALESCE(school_id, ''));

CREATE INDEX IF NOT EXISTS uploads_school_period_idx
  ON uploads(school_id, reporting_period);
CREATE INDEX IF NOT EXISTS member_snapshot_records_school_idx
  ON member_snapshot_records(school_id);

VALUES ('zamboanga-sibugay', 'Zamboanga Sibugay')
ON CONFLICT(id) DO NOTHING;

-- Master school directory (ListofSchool.xlsx, 507 schools)

VALUES ('email-policy-deped-gov-ph', 'deped.gov.ph', 1)
ON CONFLICT(domain) DO NOTHING;

-- Backfill school_id for member uploads that encode the school in the filename
UPDATE uploads
SET school_id = substr(
  substr(original_filename, instr(original_filename, 'deped-school-id-') + 16),
  1,
  instr(substr(original_filename, instr(original_filename, 'deped-school-id-') + 16), '-') - 1
)
WHERE module = 'member'
  AND school_id IS NULL
  AND instr(original_filename, 'deped-school-id-') > 0;

UPDATE member_snapshot_records
SET school_id = (
  SELECT u.school_id
  FROM snapshots s JOIN uploads u ON u.id = s.upload_id
  WHERE s.id = member_snapshot_records.snapshot_id
)
WHERE school_id IS NULL;

UPDATE member_snapshot_records
SET school_name = (
  SELECT sc.school_name FROM schools sc WHERE sc.school_id = member_snapshot_records.school_id
)
WHERE school_name IS NULL AND school_id IS NOT NULL;
